@Override
    public void onLivingUpdate() {
        super.onLivingUpdate();

        // Static Aura Attack:
        if(!this.getEntityWorld().isRemote && ++this.aoeAttackTick == (this.isPetType("familiar") ? 100 : 40)) {
            this.aoeAttackTick = 0;
            List aoeTargets = this.getNearbyEntities(EntityLivingBase.class, null, 4);
            for(Object entityObj : aoeTargets) {
                EntityLivingBase target = (EntityLivingBase)entityObj;
                if(target != this && !(target instanceof IGroupElectric) && this.canAttackClass(entityObj.getClass()) && this.canAttackEntity(target) && this.getEntitySenses().canSee(target)) {
                    target.attackEntityFrom(DamageSource.causeMobDamage(this), this.getAttackDamage(1));
                }
            }
        }
        
        // Particles:
        if(this.getEntityWorld().isRemote) {
            //this.getEntityWorld().spawnParticle(EnumParticleTypes.CLOUD, this.posX + (this.rand.nextDouble() - 0.5D) * (double) this.width, this.posY + this.rand.nextDouble() * (double) this.height, this.posZ + (this.rand.nextDouble() - 0.5D) * (double) this.width, 0.0D, 0.0D, 0.0D);
            
            List aoeTargets = this.getNearbyEntities(EntityLivingBase.class, null, 4);
            for(Object entityObj : aoeTargets) {
                EntityLivingBase target = (EntityLivingBase)entityObj;
                if(this.canAttackClass(entityObj.getClass()) && this.canAttackEntity(target) && this.getEntitySenses().canSee(target)) {
                    this.getEntityWorld().spawnParticle(EnumParticleTypes.CRIT_MAGIC, target.posX + (this.rand.nextDouble() - 0.5D) * (double) target.width, target.posY + this.rand.nextDouble() * (double) target.height, target.posZ + (this.rand.nextDouble() - 0.5D) * (double) target.width, 0.0D, 0.0D, 0.0D);
                }
            }
        }
    }

public boolean canAttackEntity(EntityLivingBase targetEntity) {
		if(!CreatureManager.getInstance().config.mobsAttackVillagers && targetEntity instanceof EntityVillager) {
			return false;
		}

		// Players:
        if(targetEntity instanceof EntityPlayer) {
            EntityPlayer targetPlayer = (EntityPlayer)targetEntity;
            if(targetPlayer.capabilities.isCreativeMode) {
				return false;
			}
        }

        // Team:
		if(this.isOnSameTeam(targetEntity)) {
			return false;
		}

        // Creatures:
        if(targetEntity instanceof EntityCreatureBase) {
			EntityCreatureBase targetCreature = (EntityCreatureBase)targetEntity;
            if(targetCreature.getMasterTarget() == this) {
				return false;
			}
            if(!(this instanceof IGroupBoss)) {
                if(!this.isTamed()) {
					if(targetEntity instanceof IGroupBoss) {
						return false;
					}
					if(this.isRareSubspecies()) {
						return false;
					}
				}
            }
        }

        // Inaccessible From Water:
        if(!this.isStrongSwimmer() && this.isFlying() && targetEntity.isInWater()) {
			return false;
		}

		return true;
	}

@Override
	public boolean canAttackClass(Class targetClass) {
		if(!CreatureManager.getInstance().config.mobsAttackVillagers && targetClass == EntityVillager.class)
			return false;
		return true;
	}

public boolean isPetType(String type) {
        if(!this.hasPetEntry())
            return false;
        return type.equals(this.getPetEntry().getType());
    }

public <T extends Entity> List<T> getNearbyEntities(Class <? extends T > clazz, final Class filterClass, double range) {
        return this.getEntityWorld().getEntitiesWithinAABB(clazz, this.getEntityBoundingBox().grow(range, range, range), (Predicate<Entity>) entity -> {
			if(filterClass == null)
				return true;
			return filterClass.isAssignableFrom(entity.getClass());
		});
    }

@Override
	public boolean canAttackEntity(EntityLivingBase targetEntity) {
		if(this.isPassive())
			return false;
		if(this.isTamed()) {
            if(this.getOwner() == targetEntity)
                return false;
            if(!this.getEntityWorld().isRemote) {
                boolean canPVP = this.getEntityWorld().getMinecraftServer().isPVPEnabled() && this.isPVP();
                if(targetEntity instanceof EntityPlayer && !canPVP)
                    return false;
                if(targetEntity instanceof EntityCreatureTameable) {
                    EntityCreatureTameable targetTameable = (EntityCreatureTameable)targetEntity;
                    if(targetTameable.isTamed()) {
                        if(!canPVP)
                            return false;
                        if(targetTameable.getOwner() == this.getOwner())
                            return false;
                    }
                }
            }
        }
		return super.canAttackEntity(targetEntity);
	}

@Override
    public void onUpdate() {
    	super.onUpdate();
    	if(!this.getEntityWorld().isRemote) {
	    	if(rapidTicks % 5 == 0 && !isDead) {
                for(int i = 0; i < 6; i++) {
                    fireProjectile();
                }
	    	}
	    	if(rapidTicks == Integer.MAX_VALUE)
	    		rapidTicks = -1;
	    	rapidTicks++;
    	}
    	
    	if(this.posY > this.getEntityWorld().getHeight() + 20)
    		this.setDead();
    	
    	if(this.ticksExisted >= this.expireTime * 20)
    		this.setDead();
    }

public void setup() {
    	this.entityName = "demoniclightning";
    	this.group = DemonMobs.instance.group;
    	this.setBaseDamage(10);
    	this.setProjectileScale(2.5F);
		this.pierce = true;
    }

public void fireProjectile() {
    	World world = this.getEntityWorld();
    	
		IProjectile projectile;
		if(this.getThrower() != null) {
			projectile = (IProjectile) new EntityDemonicSpark(world, this.getThrower());
			if(projectile instanceof Entity) {
				((Entity)projectile).posX = this.posX;
				((Entity)projectile).posY = this.posY;
				((Entity)projectile).posZ = this.posZ;
			}
		}
		else
			projectile = (IProjectile) new EntityDemonicSpark(world, this.posX, this.posY, this.posZ);
		float velocity = 1.2F;
		double motionT = this.motionX + this.motionY + this.motionZ;
		if(this.motionX < 0) motionT -= this.motionX * 2;
		if(this.motionY < 0) motionT -= this.motionY * 2;
		if(this.motionZ < 0) motionT -= this.motionZ * 2;
        projectile.shoot(this.motionX / motionT + (rand.nextGaussian() - 0.5D), this.motionY / motionT + (rand.nextGaussian() - 0.5D), this.motionZ / motionT + (rand.nextGaussian() - 0.5D), velocity, 0);
        
        if(projectile instanceof EntityProjectileBase) {
            this.playSound(((EntityProjectileBase) projectile).getLaunchSound(), 1.0F, 1.0F / (this.rand.nextFloat() * 0.4F + 0.8F));
        }
        
        world.spawnEntity((Entity) projectile);
    }

@Override
	public void onEntityCollision(Entity entity) {
    	if(this.getThrower() != null && this.getThrower().getRidingEntity() == entity) {
    		return;
		}
		if(this.getEntityWorld().getGameRules().getBoolean("mobGriefing")) {
			int explosionRadius = 2;
			if (this.getThrower() != null && this.getThrower() instanceof EntityCreatureBase) {
				EntityCreatureBase entityCreatureBase = (EntityCreatureBase) this.getThrower();
				if(entityCreatureBase.getOwner() == entity || entityCreatureBase.getControllingPassenger() == entity) {
					super.onImpact();
					return;
				}
				if (entityCreatureBase.getSubspeciesIndex() > 0) {
					explosionRadius += 2;
				}
				if (entityCreatureBase.getSubspeciesIndex() > 2) {
					explosionRadius = 2;
				}
			}
			this.getEntityWorld().createExplosion(this, this.posX, this.posY, this.posZ, explosionRadius, true);
		}
    	for(int i = 0; i < 8; ++i) {
			fireProjectile();
		}
    }

@Override
    public boolean onEntityLivingDamage(EntityLivingBase entityLiving) {
    	entityLiving.addPotionEffect(new PotionEffect(MobEffects.WITHER, this.getEffectDuration(10), 0));
		if(ObjectManager.getPotionEffect("decay") != null) {
			entityLiving.addPotionEffect(new PotionEffect(ObjectManager.getPotionEffect("decay"), this.getEffectDuration(60), 0));
		}
    	return true;
    }

@Override
    public void mountAbility(Entity rider) {
        if(this.getEntityWorld().isRemote)
            return;

        if(this.abilityToggled)
            return;

        if(this.hasPickupEntity()) {
            this.dropPickupEntity();
            return;
        }

        if(this.getStamina() < this.getStaminaCost())
            return;

        if(rider instanceof EntityPlayer) {
            EntityPlayer player = (EntityPlayer)rider;
            EntityDemonicBlast projectile = new EntityDemonicBlast(this.getEntityWorld(), player);
            this.getEntityWorld().spawnEntity(projectile);
            this.playSound(projectile.getLaunchSound(), 1.0F, 1.0F / (this.getRNG().nextFloat() * 0.4F + 0.8F));
            this.triggerAttackCooldown();
        }

        this.applyStaminaCost();
    }

@Override
     protected void onImpact(RayTraceResult rayTraceResult) {
     	 boolean collided = false;
         boolean entityCollision = false;
         boolean blockCollision = false;
     	
     	// Entity Hit:
     	if(rayTraceResult.entityHit != null) {
     		if(this.getThrower() != null && rayTraceResult.entityHit == this.getThrower())
     			return;
     		boolean doDamage = true;
 			if(rayTraceResult.entityHit instanceof EntityLivingBase) {
 				doDamage = this.canDamage((EntityLivingBase)rayTraceResult.entityHit);
 			}
 			if(!this.getEntityWorld().isRemote) {
				if (this.getThrower() == null || rayTraceResult.entityHit != this.getThrower()) {
					this.onEntityCollision(rayTraceResult.entityHit);
				}
			}
			if(doDamage) {
 				if(rayTraceResult.entityHit instanceof EntityLivingBase) {
 					EntityLivingBase target = (EntityLivingBase)rayTraceResult.entityHit;
 					if(this.onEntityLivingDamage(target)) {
 						//movingObjectPosition.entityHit.attackEntityFrom(DamageSource.causeThrownDamage(this, this.getThrower()), this.getDamage((EntityLivingBase)movingObjectPosition.entityHit));

                        boolean attackSuccess = false;
 						float damage = this.getDamage(target);

 						if(damage != 0) {
							float damageInit = damage;

							// Prevent Knockback:
							double targetKnockbackResistance = 0;
							boolean stopKnockback = false;
							if (this.knockbackChance < 1) {
								if (this.knockbackChance <= 0 || this.rand.nextDouble() <= this.knockbackChance) {
									if (target instanceof EntityLivingBase) {
										targetKnockbackResistance = target.getEntityAttribute(SharedMonsterAttributes.KNOCKBACK_RESISTANCE).getAttributeValue();
										target.getEntityAttribute(SharedMonsterAttributes.KNOCKBACK_RESISTANCE).setBaseValue(1);
										stopKnockback = true;
									}
								}
							}

							// Deal Damage:
							if (this.getThrower() instanceof EntityCreatureBase) {
								EntityCreatureBase creatureThrower = (EntityCreatureBase) this.getThrower();
								attackSuccess = creatureThrower.doRangedDamage(target, this, damage);
							}
							else {
								double pierceDamage = 1;
								if (damage <= pierceDamage)
									attackSuccess = target.attackEntityFrom(DamageSource.causeThrownDamage(this, this.getThrower()).setDamageBypassesArmor().setDamageIsAbsolute(), damage);
								else {
									int hurtResistantTimeBefore = target.hurtResistantTime;
									target.attackEntityFrom(DamageSource.causeThrownDamage(this, this.getThrower()).setDamageBypassesArmor().setDamageIsAbsolute(), (float) pierceDamage);
									target.hurtResistantTime = hurtResistantTimeBefore;
									damage -= pierceDamage;
									attackSuccess = target.attackEntityFrom(DamageSource.causeThrownDamage(this, this.getThrower()), damage);
								}
							}

							this.onDamage(target, damageInit, attackSuccess);

							// Restore Knockback:
							if (stopKnockback) {
								target.getEntityAttribute(SharedMonsterAttributes.KNOCKBACK_RESISTANCE).setBaseValue(targetKnockbackResistance);
							}
						}
 					}
 				}
 			}
 			collided = true;
            entityCollision = true;

     		int i = (int)Math.floor(rayTraceResult.entityHit.posX);
     		int j = (int)Math.floor(rayTraceResult.entityHit.posY);
            int k = (int)Math.floor(rayTraceResult.entityHit.posZ);
            BlockPos pos = new BlockPos(i, j, k);
            if(!this.getEntityWorld().isRemote && this.canDestroyBlock(pos)) {
            	try {
					this.placeBlock(this.getEntityWorld(), pos);
				}
				catch(Exception e) {}
			}
     	}
     	
     	// Block Hit:
     	else {
			int i = rayTraceResult.getBlockPos().getX();
			int j = rayTraceResult.getBlockPos().getY();
			int k = rayTraceResult.getBlockPos().getZ();
			BlockPos blockPos = new BlockPos(i, j, k);
			IBlockState blockState = this.getEntityWorld().getBlockState(blockPos);
			if (blockState.getBlock() instanceof BlockTallGrass || blockState.getBlock() == Blocks.DOUBLE_PLANT) {
				if (this.cutsGrass) {
					world.destroyBlock(blockPos, false);
				}
			}
			else {
				collided = blockState.getMaterial().isSolid();
				if (!this.waterProof && blockState.getMaterial() == Material.WATER) {
					collided = true;
				}
				if (!this.lavaProof && blockState.getMaterial() == Material.LAVA) {
					collided = true;
				}
			}
             
 	        if(collided) {
                blockCollision = true;
 	            switch(rayTraceResult.sideHit) {
                    case DOWN:
 		                --j;
 		                break;
                    case UP:
 		                ++j;
 		                break;
                    case SOUTH:
 		                --k;
 		                break;
                    case NORTH:
 		                ++k;
 		                break;
                    case WEST:
 		                --i;
 		                break;
                    case EAST:
 		                ++i;
 	            }

                BlockPos pos = new BlockPos(i, j, k);
 	            if(!this.getEntityWorld().isRemote && this.canDestroyBlock(pos)) {
 	            	try {
						this.placeBlock(this.getEntityWorld(), pos);
					}
					catch(Exception e) {}
				}
 	        }
     	}
     	
     	if(collided) {
 	    	// Impact Particles:
 	        if(!this.getEntityWorld().isRemote) {
				this.onImpact();
			}
 	        else {
				this.onImpactVisuals();
			}
 	        
 	        // Remove Projectile:
            boolean entityPierced = this.pierce && entityCollision;
            boolean blockPierced = this.pierceBlocks && blockCollision;
 	        if(!this.getEntityWorld().isRemote && !entityPierced && !blockPierced) {
 	            this.setDead();
				if(this.getImpactSound() != null) {
					this.playSound(this.getImpactSound(), 1.0F, 1.0F / (this.getEntityWorld().rand.nextFloat() * 0.4F + 0.8F));
				}
 	        }
     	}
     }

@Override
    public void onUpdate() {
    	this.updateTick++;

        if(!this.movement) {
            this.inGround = false;
            this.timeUntilPortal = this.getPortalCooldown();
        }
        double initX = this.posX;
        double initY = this.posY;
        double initZ = this.posZ;

		super.onUpdate();

        if(!this.movement) {
            this.posX = initX;
            this.posY = initY;
            this.posZ = initZ;
            this.motionX = 0;
            this.motionY = 0;
            this.motionZ = 0;
            this.setPosition(this.posX, this.posY, this.posZ);
        }

    	this.isInWeb = false;
    	
    	// Terrain Destruction
    	if(!this.getEntityWorld().isRemote) {
    		if(!this.waterProof && this.isInWater())
    			this.setDead();
    		else if(!this.lavaProof && this.isInLava())
    			this.setDead();
    	}
        if(!this.getEntityWorld().isRemote || this.clientOnly) {
            if(this.projectileLife-- <= 0)
                this.setDead();
        }

        // Sync Scale:
        if(this.getEntityWorld().isRemote) {
            this.projectileScale = this.dataManager.get(SCALE);
        }

        // Animation:
        if(this.animationFrameMax > 0) {
            if (this.animationFrame == this.animationFrameMax || this.animationFrame < 0)
                this.animationFrame = 0;
            else
                this.animationFrame++;
        }
    }

public boolean canDamage(EntityLivingBase targetEntity) {
         if(this.getEntityWorld().isRemote)
             return false;

    	 EntityLivingBase owner = this.getThrower();
	     if(owner != null) {

            if(owner instanceof EntityCreatureBase) {
                EntityCreatureBase ownerCreature = (EntityCreatureBase)owner;
                if(!ownerCreature.canAttackEntity(targetEntity))
                    return false;
            }
	    	
	    	// Player Damage Event:
		    if(owner instanceof EntityPlayer) {
		    	if(MinecraftForge.EVENT_BUS.post(new AttackEntityEvent((EntityPlayer)owner, targetEntity))) {
		    		return false;
		    	}
		    }
		    
		    // Player PVP:
		    if(!this.getEntityWorld().getMinecraftServer().isPVPEnabled()) {
		    	if(owner instanceof EntityPlayer) {
			    	if(targetEntity instanceof EntityPlayer)
			    		return false;
			    	if(targetEntity instanceof EntityCreatureTameable) {
			    		EntityCreatureTameable tamedTarget = (EntityCreatureTameable)targetEntity;
			    		if(tamedTarget.isTamed()) {
			    			return false;
			    		}
			    	}
		    	}
		    }
		    
		    // Friendly Fire:
		    if(owner.isOnSameTeam(targetEntity) && CreatureManager.getInstance().config.friendlyFire)
		    	return false;
	    }
	    
	    return true;
     }

