    	if(this.posY > this.getEntityWorld().getHeight() + 20)
    		this.setDead();
    }

public void applyStaminaCost() {
    	float newStamina = this.getStamina() - this.getStaminaCost();
    	if(newStamina < 0)
    		newStamina = 0;
    	this.setStamina(newStamina);
    	this.staminaRecovery = 0;
    }
